INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_10_0','沈山人懋学邀同丁光禄吴孝廉避暑饮园中','欧大任','明','好客如君少，
招携更一尊。
桂同淮士赋，
林即隐侯园。
图里疑山响，
琴边听涧喧。
千秋河朔饮，
谁解此清言。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_1','送张助甫之湖南四首','欧大任','明','开府荆湖上，
清秋建节行。
胡林仍对月，
羽扇亦谈兵。
水落黄陵庙，
天遥白帝城。
召归应旦夕，
登是厌承明。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_2','送张助甫之湖南四首','欧大任','明','喜得巴陵去，
犹堪和郢歌。
秋兰被澧浦，
木叶下沧波。
霄汉君恩远，
江潭客梦多。
向来曾磬折，
前席意如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_3','送张助甫之湖南四首','欧大任','明','几度传书至，
难期把袂游。
中原驱上驷，
南斗望孤舟。
缟带轻相赠，
绨袍老自羞。
天涯见明月，
空忆洞庭秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_4','送张助甫之湖南四首','欧大任','明','谈笑开尊处，
词人共握兰。
江声云梦转，
秋色岳阳寒。
侠气唯龙剑，
时名岂荐冠。
治书铃阁日，
须早寄长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_5','陆山人元德见过同黎秘书惟敬梁舍人思伯小酌得山字','欧大任','明','桐帽烟霞客，
相逢朝市间。
谁言碣石馆，
不似洞庭山。
调岂浮沉异，
心能去住閒。
因君招隐曲，
桂树几回攀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_6','李实夫太守将还泉南集别黎惟敬宅沈管二山人同赋得豪字','欧大任','明','海内论词伯，
宁能少尔曹。
竹留三径赋，
酒值五陵豪。
绿发抽身早，
青山阅世高。
乾坤交态在，
回首愧绨袍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_7','送顾汝脩归上海兼寄朱邦宪','欧大任','明','易水悲歌地，
如何与尔违。
天寒孤雁度，
江远一船归。
餐菊逢醪美，
羹莼问蟹肥。
朱云犹未出，
遥忆薜萝衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_8','钟天章张伯邻二户曹载酒夜过','欧大任','明','酒榼何因至，
蓬门偶一开。
谁知居士室，
犹有故人杯。
落魄看交态，
分曹见吏才。
鹔鹴吾已典，
萝月几回来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_9','冯侍御共宿归义寺禅房','欧大任','明','谁期趋府客，
同有住山心。
涧鹿窥禅诵，
林猿听苦吟。
清斋黄菊冷，
孤磬白云深。
安石膺朝寄，
幽盟未敢寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_10','答曾缮部省中见招','欧大任','明','省署散群吏，
知君绕径行。
听松心独远，
把菊句还成。
簪组时人态，
浮沉大隐情。
谁当虚左待，
宾客老侯生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_11','与黎秘书夜集曾缮部省中得花字','欧大任','明','官舍绕霜花，
邀欢兴未涯。
雁鸿秋万里，
砧杵夜千家。
明月松杉直，
高天河汉斜。
潘郎宁拙宦，
词赋满京华。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_12','送潘时服省觐还吴兴','欧大任','明','同待公车诏，
秋风一骑还。
以吾思问寝，
羡尔去承颜。
钓鲤太湖水，
采芝天目山。
故人期握手，
春色到燕关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_13','送张山人碵夫游东岳','欧大任','明','支瓢不惮远，
东谒泰山君。
河带泠泠水，
松栖片片云。
玉书窗下诵，
金策月中闻。
归上诸儒议，
千秋汉禅文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_14','黎惟敬初度曾缮部有作即席索和','欧大任','明','市隐扬云宅，
风流贺监年。
清歌停座上，
紫气落尊前。
词赋谁争长，
婵娟却自怜。
金门沉陆久，
那识是神仙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_15','送何别驾见可之晋陵','欧大任','明','佐郡推经术，
名儒出汉庭。
严霜醒蓟酒，
落月引吴舲。
稻熟荆溪馆，
鲈肥笠泽亭。
延州歌颂在，
谁共使君听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_16','范员外见访偶出不得款待柬谢一首','欧大任','明','子猷非兴尽，
犹是雪中回。
终愧凿坏遁，
难逢结驷来。
芸窗黄叶积，
蒿径白云开。
更枉夷门顾，
清尊得共陪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_17','送陆元德还山二首','欧大任','明','洛下辞伧父，
咸阳厌布衣。
遂成歌凤隐，
不为忆鲈归。
名岂菰蒲掩，
身才糠籺肥。
赁舂今且去，
吾道未全非。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_18','送陆元德还山二首','欧大任','明','谁念客游者，
归装无一金。
检书黄叶积，
荷锸白云深。
亲膳供莼菜，
官租指橘林。
因君寻甪里，
先寄五湖心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_19','姚元白黎惟敬张羽王见过小酌得孤字','欧大任','明','燕市浮沉日，
将谁向酒垆。
自难期贵客，
君肯问潜夫。
白眼千人废，
黄金一醉无。
却看星斗上，
剑气不曾孤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_20','雪中访洪山人从周不遇','欧大任','明','一径无车马，
相寻且杖藜。
戴因招隐忆，
袁岂避人栖。
仗虎炉空在，
笼鹅帖懒题。
蹇驴何处去，
应过灞桥西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_21','岁晏旅中寄故园诸子十二首','欧大任','明','鹤氅高斋日，
貂裘久客间。
饥寒驱我出，
鱼菽羡君閒。
落羽栖燕渚，
归心度汉关。
故乡兵甲后，
那得帛书还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_22','岁晏旅中寄故园诸子十二首','欧大任','明','严遵常闭肆，
匡鼎亦传经。
短褐谁曾问，
哀歌只自听。
观棋多妙理，
嗜酒且沉冥。
楚客宁知此，
江潭赋独醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_23','岁晏旅中寄故园诸子十二首','欧大任','明','柴荆君独掩，
怀抱向谁开。
日惨朱旗闪，
云愁白雁来。
蒯缑多侠气，
草屦老生涯。
二仲应相过，
江乡望我回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_24','岁晏旅中寄故园诸子十二首','欧大任','明','故人无一字，
目极为伤神。
虎观求方急，
牛衣卧独贫。
罪言忧战伐，
饥色杂风尘。
岂不怜同舍，
飘零万里身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_25','岁晏旅中寄故园诸子十二首','欧大任','明','论交兄弟少，
每忆长公诗。
书札能相慰，
干戈未可期。
铜鞮君隐早，
玉笈我归迟。
知有青箱在，
行藏任鬓丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_26','岁晏旅中寄故园诸子十二首','欧大任','明','与君期出世，
那复待玄纁。
聊试漆园吏，
将寻沧海君。
玉颜如可驻，
金液早须分。
南北艰虞日，
椷书报白云。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_27','岁晏旅中寄故园诸子十二首','欧大任','明','寒霄频梦远，
多在故人家。
箫咽云成䌽，
杯深月散华。
孤亭吟列岫，
三径醉餐花。
忽复烟波外，
书归汉使槎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_28','岁晏旅中寄故园诸子十二首','欧大任','明','扁舟相访处，
浑似武陵溪。
岁月期看竹，
风烟忆杖藜。
橘林双渡口，
草阁万峰西。
斥堠年年远，
重来路恐迷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_29','岁晏旅中寄故园诸子十二首','欧大任','明','昔年台尚好，
共隐大科南。
犬护山厨火，
猿听海客谈。
烟中捐蕙佩，
云里锁松庵。
君自谙吾性，
移文亦不惭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_30','岁晏旅中寄故园诸子十二首','欧大任','明','阮氏仲客贤，
名家业已传。
峤南霜橘帖，
海上牡丹篇。
远信劳鱼素，
穷交念酒钱。
崇兰君莫寄，
抽思向江天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_31','岁晏旅中寄故园诸子十二首','欧大任','明','故园多难日，
消息尚纷纭。
朋旧空相忆，
安危久未闻。
兵骄寻狭战，
戍苦伏波军。
问讯沧洲上，
渔樵亦可群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_32','岁晏旅中寄故园诸子十二首','欧大任','明','苦忆江楼别，
北来音信疏。
曾投章甫去，
几卜杜陵居。
岭峤仍烽火，
朝廷问捷书。
不知溪上客，
入幕策何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_33','雪中送别姚元白还金陵','欧大任','明','寒城一以别，
晓骑发卢沟。
燕代千山过，
关河大传游。
鸡声惊叠鼓，
雪片乱征裘。
去听江南笛，
应思倦客愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_34','吴明卿自闽至寒夜同集吴约卿谒舍得明字','欧大任','明','何期燕市酒，
并得楚狂生。
词赋空时辈，
歌呼岂世情。
幔亭云片落，
碣石雪花明。
莫问垆头夜，
沉酣有步兵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_35','同吴员外过韩员外子成宅饮时子成以病在告','欧大任','明','病爱枚乘笔，
闲资季重谈。
颇从京洛下，
一望石湖南。
月俸还官藉，
山经与客参。
何因歌九辨，
憔悴忆江潭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_36','吴侍御席上赠门人张玉归武定省觐','欧大任','明','两月传经去，
宁亲借使骢。
席常虚待左，
道岂敢云东。
射策张家子，
能诗任氏童。
苍苍岱云里，
何处听春鸿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_37','岁尽独卧长安客舍怀文休承','欧大任','明','公车同此夕，
别去又经年。
格五无宣召，
朱儒自俸钱。
孤灯残雪后，
乱帙小窗前。
谁共文江客，
屠苏一醉眠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_38','同明卿惟敬过约卿宅得朝字时除前一夕','欧大任','明','坐期官烛尽，
且以永今宵。
纵酒惟吾辈，
狂歌有圣朝。
胜传金缕蝶，
颂倚玉盘椒。
城角风前断，
空闻枥马骄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_39','人日同张山人孙鸿胪徐文学集诚意伯刘公宅得盘字','欧大任','明','西堂冠剑合，
春酒一筵欢。
七叶蓂初长，
千条柳尚寒。
河山连甲第，
歌管荐辛盘。
华胜风前影，
持觞几度看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_40','同黎惟敬询韩子成病','欧大任','明','同是沉冥客，
言寻消渴人。
避諠三署夕，
归计五湖春。
玄晏成书早，
维摩示病真。
相将江乘浦，
烟艇共垂纶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_41','同黎惟敬询韩子成病','欧大任','明','同谢鹓鸿侣，
而私丘壑身。
赐衣沽酒尽，
积俸买山贫。
梦蝶閒园吏，
怀荃托楚臣。
因君上书早，
偏忆岭南春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_42','春日同社诸公集道院咏雪得庭字','欧大任','明','岁献云含白，
春回树失青。
鸾骖停玉笥，
鹤氅肃金庭。
梅萼丛丛湿，
松枝片片零。
何当笙磬发，
同听蕊珠经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_43','春夜大雪骑过明卿邸中','欧大任','明','山阴吾兴剧，
一骑偶冲寒。
栖凤银成阙，
游龙玉作鞍。
云中妆树出，
空里散花残。
为爱阳春曲，
来同郢客看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_44','十三夜同苏子川黎惟敬方德新吴明卿苏子冲成仁卿黄定甫集吴约卿观灯得开字','欧大任','明','银缸生暖色，
谁省在霜台。
月傍琼枝出，
花攒火树开。
杯盘欢五夜，
赋颂见群才。
隐隐闻歌笑，
鸾舆太乙回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_45','陆华父金元宾邀饮灵济宫赵道士馆','欧大任','明','同作华阳客，
过从惬素情。
市朝多大隐，
喧寂共浮生。
坛石流云湿，
山钟过雪清。
问君携手约，
金液几时成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_46','范方伯职方兄弟邀同吴太守庄黄二文学汪吴二山人夜集分得兵字','欧大任','明','华筵逢二陆，
春色凤皇城。
一雨沉花气，
千门过雁声。
狂歌何处客，
浊酒此时情。
竹径风流在，
谁如阮步兵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_47','酬厉都谏滦河见寄','欧大任','明','憔悴投荒去，
何年祀碧鸡。
谁怜青琐客，
自老白云栖。
碣石春涛外，
卢龙暮角西。
安危还寄托，
健饭且扶藜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_48','期陈明府子野晚过','欧大任','明','君岂陈惊座，
邀欢满汉都。
懒朝仍傲吏，
纵饮亦吾徒。
夕苑千花暗，
春沟片月孤。
糟床堪一斗，
乘兴肯来无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_49','题冯汝行海浮山居图','欧大任','明','远识金银气，
舟行望转微。
楼台疑蜃起，
风雨挟鹏飞。
孤岛分齐鲁，
千山入海沂。
图南吾欲去，
渺渺泛潮归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_50','曾缮部省中夜赏牡丹得狂字','欧大任','明','官阁题诗夜，
重陪水部郎。
花摇池槛影，
酒洽竹林狂。
国色含烟紫，
宫妆写额黄。
月中看不足，
汉署更闻香。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_51','送冯明府谪教润州','欧大任','明','讲肆延陶令，
今非马队扃。
葛巾原漉酒，
绛帐且传经。
高浪西津白，
生烟北固青。
江南书札近，
好寄鹤丘铭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_52','送陈子野调令宁乡','欧大任','明','古来才子地，
天遣到长沙。
谁道三湘水，
今看一县花。
橘洲收井税，
竹浪见人家。
君自谈云梦，
无令楚客誇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_53','送丁子文赴浙省','欧大任','明','名士曾书记，
之官亦散曹。
登楼中夜月，
作赋曲江涛。
荷叶迎仙棹，
薇花洒客袍。
知君还北望，
离思满烟皋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_54','太保刘文安公彰恩卷','欧大任','明','功德四朝日，
河汾千载馀。
曲台家乘礼，
东观世藏书。
诵岂多三箧，
名因出九胪。
殿前曾剑履，
师傅几人如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_55','太保刘文安公彰恩卷','欧大任','明','风雨中台坼，
笳箫上党寒。
崇班瞻太保，
旧学失甘盘。
瓜奠频繁遣，
槐阴次第看。
凤毛今五色，
得恐谢家难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_56','午日集周都督子脩宅得诗字','欧大任','明','缓带从容日，
天中盛赋诗。
总戎周太尉，
好客郑当时。
射柳无劳试，
觞蒲且共持。
陆沉金马下，
三见汉宫丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_57','病中承曾缮部见召不赴缮部以予将归曾有二诗意最勤厚因并酬答','欧大任','明','倦游仍伏枕，
归思更何如。
君已怜将别，
吾方念介居。
家贫沧海钓，
身老茂陵书。
知有盈觞酒，
还来伴直庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_58','送刘伯良宰信宜','欧大任','明','明卿春出牧，
慷慨又刘生。
邸吏惊怀印，
都人羡请缨。
云随铜柱尽，
山过窦州平。
我欲移家去，
鸣弦听诵声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_59','送从弟淳伯南归二首','欧大任','明','三载惊相见，
都亭把袂时。
游梁吾已倦，
入洛尔何迟。
谁诵淩云赋，
仍为失路悲。
天涯贫贱别，
只少杜陵诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_60','送从弟淳伯南归二首','欧大任','明','同有怀萱梦，
而先戏彩欢。
朝餐行荐笋，
秋佩且纫兰。
山笥归时检，
尘冠异日弹。
长安春柳色，
还待玉骢看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_61','夏日同潘时良出访徐子与因避暑张园','欧大任','明','休沐名园里，
飞觞细雨前。
瓜期元不偶，
萍迹况相怜。
避暑仍袁绍，
登楼亦仲宣。
何须仙掌露，
心赏已泠然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_62','夏日同潘时良出访徐子与因避暑张园','欧大任','明','空庭回赤日，
万竹驻高轩。
入座凉飙满，
披襟玉露繁。
风尘俱傲吏，
河朔一清尊。
即此看沉陆，
无论金马门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_63','同徐子与使君过袁鲁望进士留酌','欧大任','明','燕市吾徒在，
相携片语真。
饥寒驱薄宦，
簪绂偶时人。
醉看青萍短，
娇歌白纻新。
君看袁夏甫，
落落傍风尘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_64','同曾缮部宿省中得园字','欧大任','明','邀欢成伴直，
退食一清尊。
画省更明月，
铜驼非故园。
竹阴凉露滴，
楼影夜乌翻。
看尔郎官草，
青绫怀主恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_65','方侍御德新宅伏日同诸公宴集得台字','欧大任','明','青骢人正避，
皂帽客犹来。
酒以金鱼换，
谈容玉麈陪。
迎风开岳色，
消暑倚霜台。
君已投车辖，
那能不醉回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_66','病中顾汝所招饮不赴闻是日子与先归鲁望吐酒有污茵之句因以戏之','欧大任','明','消渴难乘兴，
空斋独闭关。
最思光禄酒，
一望太行山。
客劝袁丝饮，
人歌山简还。
不知谁戏剧，
噀雨到人间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_67','伏日同徐子与顾汝和袁鲁望沈道桢顾汝所集文寿承斋中得家字','欧大任','明','同心曾海岳，
握手偶京华。
酒狎高阳侣，
诗称博士家。
盘冰寒苜蓿，
井碧泛甘瓜。
独有留欢处，
空庭日易斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_68','送杨朝藩掌教安仁','欧大任','明','洞庭南去路，
文学得君良。
地以琳琅重，
洲因橘櫾香。
听猿过楚岫，
看雁到衡阳。
莫道王程远，
由来近帝乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_69','送张彦旬掌教诸城','欧大任','明','赐履千秋地，
谭经五岭豪。
汉儒称世业，
齐客亦吾曹。
马耳登台见，
琅琊出浪高。
傥能游海上，
为我访卢敖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_70','立秋日同文寿承徐子与顾汝和沈道桢顾汝所朱子愚饮袁鲁望宅得凉字','欧大任','明','秋催词客赋，
晚醉酒人傍。
纨扇西风早，
絺衣白露凉。
落梅惊玉笛，
坠叶响银床。
惟有潘郎鬓，
飘零感异乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_71','送王茂成归括苍','欧大任','明','骏足图难索，
蛾眉画莫凭。
盐车曾涕泪，
国色未须矜。
秋菊怀三径，
燕歌别五陵。
大楼岩下月，
谁得伴支藤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_72','送王茂成归括苍','欧大任','明','今日中原客，
秋风送汝还。
五噫辞汉主，
一骑出秦关。
醉眼功名际，
浮云去住间。
黄精归可斸，
且看浙西山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_73','七夕遇雨同徐使君袁进士刘沈二山人集潘大理宅时子与已有长芦之役','欧大任','明','月卿重促宴，
星使欲临河。
急雨下秋叶，
平池生夕波。
风前双掌出，
云里二灵过。
且莫捐兰佩，
其如怅别何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_74','曾缮部以三宅饯徐使君子与得情字','欧大任','明','故人今夕酒，
砧杵凤皇城。
碣石片云落，
渔阳孤月明。
佩刀看侠气，
击筑共平生。
别后南皮客，
应知汉署情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_75','观上虞谢进士读书山房图','欧大任','明','东山君早出，
人忆著书年。
竹牖飘晴叶，
松门起夕烟。
经声秋瀑下，
笔札白云边。
久系苍生望，
深知谢傅贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_76','赠张仲实还山','欧大任','明','曾闻飞遁日，
石上卧江烟。
芝术君何弃，
藤萝我最怜。
几时沧海钓，
一问赤松年。
归去看云起，
青苔诵古篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_77','初秋夜过曾以三缮部得尊字','欧大任','明','凉色爱清尊，
银鞍夜到门。
知予思露掌，
为客扫风轩。
满目时人态，
平生国士恩。
片心秋月下，
微尔共谁论。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_78','暮秋过饮戴氏西园','欧大任','明','羸马青门路，
君家数往还。
亭留白云曲，
城倚太行山。
残菊寒犹摘，
霜梨醉可攀。
山阳灌园日，
谁共吕安閒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_79','送陈郑州敬甫兼寄张判官','欧大任','明','词人多出牧，
州郡岂徒劳。
汉主分符竹，
王郎揖佩刀。
楼前中岳树，
雪后大河涛。
知授梁园简，
应邀谢法曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_80','送刘山人子脩归真州','欧大任','明','三年蓟门客，
分手秋风时。
旅食金同尽，
生涯剑独知。
柴荆归更掩，
猿鹤隐何疑。
我识江头路，
寻君定有期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_81','怀苏子冲','欧大任','明','闻道辟疆园，
蓬蒿积短垣。
诗篇传海岳，
剑术老乾坤。
判袂燕台侧，
题书濮水原。
相思日南北，
吾亦别金门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_82','寄苏子长','欧大任','明','季子貂裘在，
何年作隐沦。
金扉曾谢禄，
瑶草足娱亲。
林似听莺日，
山疑卧虎春。
悠悠濮台水，
今见钓鱼人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_83','寄苏子新','欧大任','明','敬客知公子，
通家托长兄。
早传梅石赋，
不负竹林情。
开径期羊仲，
淩云羡马卿。
思君若河水，
何以到鄄城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_84','雷比部携酒同古比部夜过得何字','欧大任','明','寂寞无奇字，
其如载酒何。
秋辞三署直，
夜向五陵过。
玉笛吹花早，
银床坠叶多。
他宵明月下，
荒径忆鸣珂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_85','子与将之瑞州予亦南行寄此为别','欧大任','明','量移劳圣主，
尺组不须论。
山雪思君曲，
江枫去国恩。
孤村通栗里，
三谷近麻源。
独有天涯客，
扁舟夜听猿。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_86','酬张山人英甫','欧大任','明','蓟北逢君日，
名山忆永嘉。
䌽毫新赋颂，
铁研老生涯。
酒伴灵台月，
心期雁荡霞。
谁堪关路别，
惆怅五陵花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_87','题张仲素玄玉斋','欧大任','明','高斋弦诵日，
鸣佩更珊珊。
江泻瑶池色，
窗摇玉树寒。
何来沧水使，
将献白云坛。
牛斗千山外，
晴虹几度看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_88','送董山人述夫归阳羡别业','欧大任','明','远游因好道，
能诵五千文。
帽湿双林雨，
衣披十岳云。
江湖犹作客，
猿鹤正思君。
归去张公洞，
秋天长啸闻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_89','九月十五夜月','欧大任','明','瑶草三秋色，
金风一夕寒。
书缘多难绝，
月在异乡看。
凄断惊霜角，
迟回望露盘。
刀头今未定，
谁最忆长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_90','张户部伯邻宅同郭仪部方尚宝夜集','欧大任','明','菊觞宁厌数，
骑马屡过门。
结客多同舍，
看花似故园。
月高燕市路，
砧近汉宫垣。
不有中郎酒，
谁堪秋思繁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_91','晚过许维桢王绍传二内翰院署对酒言别','欧大任','明','玉署能迎客，
高天近九重。
白云随匹马，
紫气护双龙。
洒袂西山雪，
持觞北禁钟。
周南他日路，
思尔扈登封。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_92','景州谒董子祠','欧大任','明','广川晴雪后，
驻马董生祠。
帷在知曾下，
园荒似不窥。
疏林堕残叶，
枯柳宿寒鸱。
老作江都客，
传经愧我师。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_93','阙里观先师所植桧','欧大任','明','尚见参天起，
今思翠黛长。
岁华周日月，
春色鲁宫墙。
柏岂存新甫，
桐虚表峄阳。
独馀嘉树在，
海岱接扶桑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_94','谒颜庙','欧大任','明','睎颜曾想像，
入室见琴书。
洙泗为邻并，
箪瓢恒晏如。
山庭仍陋巷，
井里半荒墟。
目送浮云过，
因知乐有馀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_95','谒孟庙','欧大任','明','世岂居邹日，
三迁有故宫。
龟蒙曾蔽鲁，
凫峄只荒东。
客礼兼金外，
家祠五鼎中。
玄圭同禹力，
谁颂决河功。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_96','枫香驿楼夜雪','欧大任','明','白马枫香下，
青春粉荔前。
雪凝千涧水，
风荡万家烟。
卯酒官亭路，
辛盘旅食年。
故人传尺素，
为枉济江篇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_97','立春日匡庐山中','欧大任','明','两见青丝菜，
五年今复游。
客从庐岳下，
僧候虎溪头。
春转双林色，
冰开众壑流。
天池飞梦到，
宁待拂衣秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_98','经濂溪先生故居','欧大任','明','斯人不可作，
绝学已千年。
湓浦庭皆草，
匡庐岳是莲。
霜凋前代树，
月霁一林烟。
犹有图书在，
风琴自洒然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_99','同介上人寻广福观遇刘道士','欧大任','明','高赏云霞侣，
欣然巾我车。
法师不嗜酒，
道士本能书。
炉耸紫烟际，
经残丹笈馀。
虎溪还一笑，
忘却在匡庐。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_100','青居馆读江州故守朱子价碑','欧大任','明','谢公文可读，
山馆不荒芜。
星堕炉峰顶，
珠沉甓社湖。
虎符丹旐远，
龟碣白云孤。
千载匡君传，
能留姓字无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_101','圆通寺','欧大任','明','山有古祇林，
开堂石耳阴。
岳云当涧落，
径树向门深。
雪磴僧支策，
风泉客掩琴。
西亭茶灶在，
即此长禅心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_102','元夕玉峡过吉水与黎比部饮舟中','欧大任','明','雪浪开千里，
仙槎偶共乘。
江亭深夜酒，
水市满船灯。
笛里听金缕，
帆前望玉绳。
明年花月夕，
还约醉兰陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_103','安远驿下送别叶男兆宰福清','欧大任','明','天边叶县令，
何日别皇畿。
驿树迎官舫，
江云映彩衣。
辱楼沧海近，
雁字晋安稀。
期尔陪仙仗，
双凫正北飞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_104','清远道中答胡佥宪','欧大任','明','结束事行役，
风霜易白头。
望乡同海雁，
浪迹似沙鸥。
岐路频搔首，
江山一倚楼。
欲裁王粲赋，
幸托李膺舟。
北上初辞粤，
西归已梦周。
本非游说客，
空愧黑貂裘。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_105','谒少司寇梅国刘公祠','欧大任','明','丁年予度岭，
公已蚤归休。
旅馆回光盻，
林园表宴游。
每闻诸士论，
实许五臣流。
富国卑为晏，
精忠更是刘。
深衷劳奏疏，
雅量镇沉浮。
献纳趋宸扆，
班司近冕旒。
不鸣羞仗马，
遂去伴江鸥。
田宅贫萧相，
朝廷老沈侯。
蒲轮将下日，
梁木已先秋。
伏腊村翁走，
碑铭太史留。
何人哀北海，
有客哭西州。
寂寞祠前路，
空瞻庾岭头。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_106','过汤阴谒岳忠武庙','欧大任','明','遥指汤阴路，
西寻鄂国居。
行云犹惨淡，
征马尽踌躇。
逆虏兵曾炽，
中原愤未除。
旄头南落日，
鼓角北征馀。
谋国奸先蠹，
和戎策已疏。
黄龙期痛饮，
丹诏促归与。
草染苌弘血，
霜飞乐毅书。
皇天不可问，
烈士竟何如。
力尽朱仙镇，
魂随二帝车。
山河留壮气，
不敢泣欷歔。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_107','秋夕约卿元白惟敬同集小斋闻新雁得年字','欧大任','明','秋风万里至，
一雁过长天。
嘹唳胡笳里，
凄凉塞笛前。
庭空飘落叶，
家远梦江船。
声急零霜夕，
书迟度岭年。
罗浮归未得，
沧海到应先。
楚客谁同听，
西楼片月悬。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_108','春夜同惟敬约卿集寿承学舍时休承将之吉水在坐同赋得寒字','欧大任','明','庭阶仍系马，
献岁聚长安。
甲子新周朔，
申公老汉冠。
共推经术最，
其奈鬓丝残。
学馆荣三绝，
儒林合二难。
兴来题棐几，
酒至出辛盘。
墨竹烟光动，
鱼灯海色寒。
粤人千里思，
楚客几回看。
凤掖怜分袂，
螺洲忆采兰。
雪消梅粉路，
月满杏花坛。
他日江湖上，
方知此夕欢。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_109','春雪后同杨徐沈舒四子集诸太史宅','欧大任','明','西山残雪在，
返照万家明。
汉署宾初集，
梁园赋欲成。
门摇金马色，
树走玉龙声。
暗溜还凝水，
疏帘尚积霙。
花轻含冷萼，
草细折冰茎。
寒枥仍留骑，
深更不算觥。
璚楼惊曙雁，
银阙听新莺。
纪瑞词臣颂，
祈灵圣主情。
白云停绝唱，
黄竹念苍生。
䌷史书年异，
看君继二京。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_110','送吕参军幼开出守寻甸','欧大任','明','儒林推父子，
世德重箕裘。
家出关西学，
才参幕下筹。
符分铜虎去，
使得碧鸡游。
行矣驰滇国，
先应梦益州。
僰僮迎汉吏，
泸帅识姜侯。
万里题诗日，
千山羽猎秋。
青蛉通北望，
黑水入西流。
赐召君来速，
归期看拥驺。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_111','送秦侍御赴浙江佥宪','欧大任','明','早岁成辞赋，
君王诵子虚。
自簪前殿笔，
岂是茂陵居。
使以观风出，
名因抗疏馀。
外台仍衣豸，
南国便羹鱼。
道路秦人策，
江湖越绝书。
行歌听榜枻，
问士过桐庐。
海色长鲸截，
霜威落雁疏。
衔恩归有日，
把袂意何如。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_112','孙鸿胪席上咏樱桃得绡字','欧大任','明','珍果来何处，
炎风万里遥。
莺含分露颗，
雀啄落星条。
映席霞飞槛，
开笼绛满绡。
瑛盘行寝庙，
玉食及臣僚。
近侍初休沐，
新题偶见邀。
青冥沾赐日，
同荷圣明朝、',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_113','秋日同周象贤沈道桢游白云观','欧大任','明','燕九人能往，
斯游我自偏。
长廊频落叶，
匹马独闻蝉。
鸡犬驱何日，
烟霞似昔年。
泉凝丹井月，
门锁白云天。
法磬鸣霜后，
经函散石边。
宁劳东海上，
即此候神仙。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_114','送王太史元驭奉使册封赵藩','欧大任','明','东观词臣出，
西藩旧邸开。
占星随玉节，
赋雪上铜台。
庭揖诸侯客，
园游七子才。
虎盐门下献，
牛酒里中来。
赵璧无劳赠，
吴涛更有裁。
圣明思侍从，
莫遣隔年回。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_115','出京师留别张郎中鸿与梁助教彦国十二韵','欧大任','明','朔风吹万里，
曾共忆江乡。
雁引归心早，
砧惊客梦长。
忽随公府牒，
频举故人觞。
夙昔诸生后，
周旋二子傍。
四门推助教，
三署表中郎。
韦杜衣冠并，
邹枚侍从良。
出关怜马首，
执戟羡鹓行。
雪后宫云白，
天边苑树苍。
眇予怀魏阙，
看尔在岩廊。
晨佩趋长乐，
宵钟听未央。
梅花庾岭色，
柏叶禁庭香。
莫以相如赋，
从容奏汉皇。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_116','发华节亭过灵洲至三水与钧谟猷三弟别','欧大任','明','片帆已过郁洲台，
风急惊沙落雁哀。
万里独怜难判袂，
三江犹得共衔杯。
西陵涛起思康乐，
南国书归念大雷。
弟妹分岐贫更苦，
客轺今去几时回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_117','过韶州宿芙蓉驿','欧大任','明','峡过浈阳尽始兴，
旧游名胜记吾曾。
霜天雁字孤城月，
水驿滩声一夜灯。
泷口刺船愁问吏，
曹溪飞锡欲寻僧。
夷犹更进芙蓉棹，
韶石峰头望舜陵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_118','同胡佥宪登云封寺观音阁玩梅花','欧大任','明','岭开孤阁倚巑岏，
携手高临百八盘。
山畔幽香移般若，
天边残雪落旃檀。
春催远客兼程早，
驿报长安一骑寒。
十载江南谁把玩，
北枝今日正宜看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_119','淦口望胡佥宪舟不至先赴金川驿相待','欧大任','明','江树寒深独鸟依，
邮亭回首叹蓬飞。
湓峰雁去冲残雪，
渝水帆来带落晖。
日短山城收市早，
风高溪寺听钟微。
瑶琴玉涧今何处，
水远天长客未归。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_120','雪后渡淦水至萧水寄潘少承','欧大任','明','风前淦口叹飘零，
雪后潇滩更杳冥。
问驿尚知黄蘖馆，
渡江还向渌波亭。
异乡只见山云白，
故国应多海树青。
此际想君开阁望，
计程时一展图经。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_121','雨中趋陆过瑞州','欧大任','明','朔风驱马听晨鸡，
路入筠州晚色迷。
小洞雪封梅树外，
飞霞寒挂竹林西。
自怜残腊犹奔走，
长忆他乡尚鼓鼙。
问讯谢公歌舞处，
万峰零雨一猿啼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_122','大雪宿建昌早行过德安','欧大任','明','白云千里上巑岏，
石耳香炉雪未乾。
身到昆丘群玉府，
梦游天女散花坛。
闭关岂合长高卧，
跨马偏宜半醉看。
渐过楚乡仍北望，
瑶台琼阙是长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_123','雪夜同胡伯贤宿东林寺','欧大任','明','山僧留客解征鞍，
虎笑溪桥鹤绕坛。
两寺疏钟云壑暝，
万峰积雪石门寒。
夜深窗竹惊频折，
腊尽溪梅落未残。
却望屏风飞瀑下，
何时还共醉中看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_124','晓过西林寺','欧大任','明','峰头雪霁日初升，
扶策西林问上乘。
高阁残经千劫火，
空山孤塔几传灯。
青莲旧迹谁为主，
白鹿曾游不记僧。
笑忆柴桑犹强出，
十年心寄白云层。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_125','初春三日浔阳渡江过黄梅','欧大任','明','匹马来看云锦屏，
东风湓浦又扬舲。
九江涛涌帆前白，
五老峰横雪后青。
鸿雁春归书未至，
鱼龙天阔酒初醒。
苍茫已向匡君别，
瀑布香炉绕驿亭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_126','人日由蕲水过黄州长堤四十里马上晴望','欧大任','明','蕲春城在楚云间，
策马冲寒问五关。
积雪消时浠水树，
乱峰明处汝州山。
石头古渡孤舟急，
樊口疏钟一鸟还。
记取天涯过人日，
莫愁双鬓易成班。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_127','寻东坡雪堂遂过赤壁矶下','欧大任','明','钱唐为守最风流，
谁遣临皋咏四愁。
两赋云霞留赤壁，
五年烟月醉黄州。
沙湖已决求田计，
樊口曾来把钓游。
莫向雪堂歌九辩，
江山萧瑟白云秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_128','黄州遇袁履善比部时量移郡丞','欧大任','明','天涯把袂问何之，
海内才名识汝迟。
此地更留苏氏赋，
何人不诵谢公诗。
豫章一榻将悬日，
洛下扁舟欲去时。
圣主似闻前席待，
蓟门烟柳忆归期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_129','白杲镇冒雪趋麻城寄袁履善','欧大任','明','万树官梅照酒杯，
为谁千里雪中来。
貂裘零乱飞花坠，
马足淩兢踣铁开。
草埠河将成玉渚，
木陵山已作瑶台。
却忆郡斋袁夏甫，
青绫深拥散衙回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_130','过官渡河入光山','欧大任','明','候晓津亭驿骑多，
中原道路此经过。
镇淮楼影临官渡，
浮弋山光带寨河。
白氎尚存京洛俗，
青翰空忆越人歌。
北风吹雪千馀里，
零乱貂裘奈尔何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_131','过汝南访徐子与使君','欧大任','明','望气寻君汝邓来，
乘春冰雪马前开。
周璆谬忝斋中客，
徐干今推邺下才。
坐啸试临桐柏水，
倚歌还上景夷台。
长安西去谁知己，
乞取金龟醉几回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_132','徐子与春日表台宴集得春字','欧大任','明','客来十日饮河滨，
淮蔡城边气色新。
把袂未消千里雪，
开尊先散万家春。
嵩山杳霭连王屋，
洛水萦回带孟津。
百尺高台君试望，
中原鞭弭更何人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_133','谒大复先生祠堂','欧大任','明','贤隐山前宿草烟，
祠堂今筑表台边。
伏生不待传经岁，
贾谊空伤作赋年。
客望函关仍紫气，
书藏嵩岳并青天。
从游载酒嗟予晚，
门下何人受太玄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_134','登汝南城楼','欧大任','明','将军白马旧临关，
楼橹中原战守闲。
汝曲自成悬瓠水，
淮南遥见朗陵山。
雁鸿早向春风过，
鹅鸭偏惊夜雪还。
陈蔡北来今重镇，
戍笳声在乱云间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_135','郑州客舍怀故园诸子','欧大任','明','候馆萧条一骑过，
黑貂风雪意如何。
长堤日落行人少，
远树天寒宿鸟多。
仆射陂前京北路，
武疆城畔楚西歌。
春来纵有停云句，
双鲤那因到汴河。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_136','郑州登楼望中岳','欧大任','明','名岳岧峣接上台，
毓祥今有中兴才。
云扶二室天边出，
日映三花雪后开。
周典尚馀巡狩迹，
汉家新筑集灵台。
太平不复论封禅，
时听嵩呼万岁来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_137','渡黄河','欧大任','明','津头小吏候旌干，
河激高歌举棹欢。
天转浮云酸枣决，
涛翻斜日具茨寒。
万行归雁风前过，
一片征帆树里看。
沉璧宣房非汉代，
君王无事诏千官。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_138','河上送七郡太守入洛','欧大任','明','关东犹切九重忧，
已报诸侯会洛州。
梁狱竟劳田叔按，
楚筵宁见穆生留。
嵩邙远近生寒色，
瀍涧东西急暝流。
何日山河还带砺，
词臣空忆兔园游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_139','寻空同先生河上草堂','欧大任','明','西来孤骑过中原，
却忆词人旧有园。
岳色至今干紫极，
河声犹似下龙门。
雪驱梁苑千年赋，
云惨浔阳万古冤。
荒径只今书带满，
独留玄草在乾坤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_140','汴梁怀古','欧大任','明','缥缈宫城十二楼，
玉津无复昔年游。
烟深废苑常疑雨，
柳折残堤半似秋。
遗老尚能谈楚汉，
平台谁更召枚邹。
輶轩一望中原路，
长送黄河过汴州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_141','过邺下访谢山人茂秦','欧大任','明','中原七子似君稀，
独向西河老布衣。
四海风云鸿鹄远，
五陵烟月薜萝归。
竹林青荫乌皮几，
铜雀高临白板扉。
自笑缁尘京洛去，
新诗偏忆谢玄晖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_142','丛台','欧大任','明','磁州北走邯郸道，
一上高台万里思。
马服山从低树见，
葛鹅城为浊河移。
啼乌岂是娇歌日，
衰草全非袨服时。
六国不知蚕食易，
西来游客最堪疑。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_143','登龙兴寺天宁阁同胡佥宪伯贤阅观音像','欧大任','明','佛阁淩空百尺浮，
六鳌曾此负神丘。
金身天竺来何日，
石塔波罗到几秋。
恒岳烟消通大漠，
滹沱风急涌寒流。
凭高岂但超尘劫，
咫尺彤云是帝州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_144','初至燕京宿报国寺英上人房','欧大任','明','长途日暮叩僧扉，
疑入名山坐翠微。
高阁佛灯留客枕，
中天禅月照征衣。
不堪夜梦仍南去，
已听春鸿尽北飞。
回首缁尘心独远，
欲从初地得皈依。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_145','登毗卢阁','欧大任','明','东方初日照觚棱，
振舄冯高眼倍明。
四塞河山环大内，
诸天楼观俯沧瀛。
花台似涌云中出，
仙袂疑从岳顶行。
䌽槛雕阑闲倚遍，
九霄长送凤凰声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_146','寓黎秘书馆王全人见过','欧大任','明','献赋长安春暮来，
故人今典汉兰台。
紫貂贳酒君能过，
玉笥藏书客自开。
金马沉冥犹薄禄，
青云冠盖几怜才。
竹林正是邀欢地，
车骑良宵得共陪。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_147','吴侍御约卿宅同黎秘书惟敬杜舍人从殷得臣字','欧大任','明','日下衣冠散紫宸，
郑庄虚席正邀宾。
鹔鹴燕市频沽酒，
鸿雁胡天半过春。
自笑负薪随计吏，
偶从视草识词臣。
尊前意气惟须醉，
世路风尘白发新。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_148','和顾汝和玉河堤上见白燕','欧大任','明','海上遥思玳瑁梁，
御沟东畔几回翔。
瑶台乍过疑无影，
珠树曾栖半带霜。
风里差池飞玉舄，
月中妆束舞霓裳。
谁云京洛缁尘化，
犹自衔恩绕建章。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_149','送陈侍御道襄巡畿甸及齐鲁诸郡','欧大任','明','虎节翩翩獬豸冠，
前驱负弩渡桑乾。
花飘燕甸春风早，
雨过齐州岱色寒。
东海煮盐纾国计，
北庭飞粟募材官。
芝泥玉检登封地，
羡尔云边策马看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_150','送陈进士彦吾使密云兼还南海省觐','欧大任','明','前驱负弩驿亭间，
建节东行暂出关。
霄汉乍辞丹凤阙，
风烟先卷白檀山。
主恩远许封轺去，
家庆深欢䌽服还。
莫恋故园春草色，
汉庭郎吏待鹓班。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_151','梁彦国滦州书至','欧大任','明','疲马饥衔苜蓿嘶，
怜予千里望辽西。
风驱朔雪卢龙近，
云暗春城碣石低。
帐下谭经留客坐，
斋中把酒听莺啼。
雄文最似相如赋，
侍从河东待尔题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_152','送岑允穆司理池州','欧大任','明','春深杨柳暗燕关，
南去襜帷不可攀。
雪浪城头江祖石，
芙蓉天外李家山。
讼堂吏散莺堪听，
药院僧来鹤共闲。
秋浦看花能忆否，
封书须及早鸿还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_153','首夏沈鸿胪宅同吴侍书黎秘书顾舍人赏牡丹','欧大任','明','玉鞭遥向五陵家，
沁水园中日未斜。
万片䌽云飘翠幕，
一阑红锦照晴霞。
席茵最忆江南草，
尊酒频看蓟北花。
欢赏幸陪供奉客，
绝胜歌管七香车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_154','送王武库定甫使金陵因还南昌展省','欧大任','明','供帐都门赠柳条，
仙郎衔命下丹霄。
浮云万里辞燕甸，
明月孤亭拥汉轺。
碧草渐迷扬子渡，
青溪还问谢公桥。
过家莫羡南昌尉，
鸣玉含香满圣朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_155','同钱水部吴职方施缮部曾虞部登西山绝顶','欧大任','明','绝嶂西来翠柏残，
片霞时堕汉臣冠。
青天大岳云边出，
落日中原马上看。
玉气重关开碣石，
飞泉千折下桑乾。
欲将凫舄翩翩去，
花落天坛露正寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_156','晓出玉泉山经西湖','欧大任','明','玉泉散作镜湖波，
闻道宸游向此过。
宫阙三山浮弱水，
楼船千里度星河。
白麟朱雁无消息，
瑶草金芝近若何。
词客昔年誇扈从，
琳池花似汉时多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_157','省中芍药和惟敬','欧大任','明','苑中红药艳阳催，
禁直仙郎宴赏回。
官锦乍披青玉案，
露华深注紫霞杯。
清芬结佩佳人赠，
迟日当阶上客裁。
词赋王褒今待诏，
銮舆临幸几时来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_158','雨夜郑驾部携酒同过黎司封宅时司封已擢广西参藩','欧大任','明','佩刀解赠意踌躇，
把袂燕歌泪满裾。
客路风烟频汉诏，
主恩天地有潘舆。
蓟门夜色千家雨，
桂海秋涛九月书。
乡里衣冠吾独后，
淩云空自老相如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_159','雨中过周园访沈山人与姜膳部对酒作','欧大任','明','虎林词客宿称豪，
下马何人问浊醪。
醉里山连秦苑树，
赋成风起曲江涛。
雨深绿草胡尘断，
云散金茎汉阙高。
岂有雄文今待诏，
桓谭犹道在春曹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_160','送司封黎郎中惟和出参广西政','欧大任','明','凤城芳草散鸣珂，
横笛谁堪马上歌。
荆楚晓烟飞越巂，
湘漓秋色入牂牁。
省郎剑佩云霄远，
词客江潭岳牧多。
玉节明年应趣召，
咸阳西上莫蹉跎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_161','酬王舍人仪甫潞河见寄','欧大任','明','骊驹几日出燕关，
咫尺青云不可攀。
便访安期沧海上，
谁容方朔汉庭间。
故人书札愁中寄，
逐客风烟梦里还。
秋色王程应渐远，
知君西望太行山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_162','约卿宅同元白惟敬咏盆荷得前字','欧大任','明','华顶曾窥玉井前，
燕阳还赋九花莲。
秋风细洒池边石，
暑气全消雨后天。
鱼戏绿波经十里，
龟游清露已千年。
因思溪上芙蓉馆，
谁更菱歌上钓船。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_163','夜饮诸太史端甫宅','欧大任','明','周南初返直庐年，
朝退能开野客筵。
宫锦夜披明月下，
禁钟秋到凤楼前。
玉绳低映长安树，
仙掌高擎白露天。
方朔自惭还索米，
汉庭空有故人怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_164','同元白惟敬过约卿所出鲥鱼侑酌感赋','欧大任','明','赐鲜今见出青冥，
旅食京华鬓已星。
珠履尚弹孤客铗，
金盘宁羡五侯鲭。
天遥渔艇三江水，
秋入鲈乡万里亭。
何处沧洲无钓侣，
清时犹自恋宸扃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_165','新秋同文寿承沈懋学文休承许殿卿姚元白黎惟敬集吴约卿高斋得飞字','欧大任','明','初闻征雁送斜晖，
凉夜高斋此会稀。
沧海月从危堞过，
太行云入小窗飞。
狂来每忆莲池咏，
醉后还寻竹径归。
万里秋风长作客，
尊前空愧薜萝衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_166','送许右史殿卿之河南','欧大任','明','曳裾闻尔相东平，
诏许亲藩借老成。
梁苑词臣齐客在，
济南经术汉家名。
驱车落日河流远，
策杖秋风岳顶行。
莫叹壮游今已倦，
主恩还遣入西京。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_167','万寿节早朝皇极门','欧大任','明','清秋阊阖曙光分，
逢掖追趋谒圣君。
南极一星珠斗近，
嵩呼三祝绛霄闻。
九傧赞后班群瑞，
八伯歌成下五云。
白雉赤麟誇盛事，
兰台还奏汉都文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_168','朝退出右掖望西苑','欧大任','明','紫宸分仗散千官，
谁奉西清曲宴欢。
瑶水风云随玉辇，
蓬莱宫殿接金銮。
九霄幡影玄坛閟，
五夜钟声碧落寒。
却忆甘泉秋色里，
侍臣多在月中看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_169','卢方伯少明入京中秋见邀玩月','欧大任','明','使车南去少能留，
此地还期月下游。
万里星环燕阙夕，
九关榆落蓟门秋。
已闻卿相频推毂，
自笑风尘老敝裘。
宾从他宵还对酒，
不知谁共庾公楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_170','十六夜小斋待月元白约卿同赋','欧大任','明','东来车骑访幽栖，
共待清光手重携。
九市烟尘人境外，
万家砧杵帝城西。
黄山远见宫槐直，
紫阁平临海树低。
何事天涯问圆缺，
故园应待尺书题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_171','十七夜同何太仆卢方伯袁节推集黎秘书宅','欧大任','明','赐金几日出西京，
秘省留欢此夕情。
渐望使星天畔去，
尚悬卿月禁边明。
腾骧独识秦关骑，
战伐曾谈涨海兵。
只尺君恩如召问，
上书何以答升平。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_172','九日同黎秘书李黄门吴冯二侍御登宣武门楼','欧大任','明','百二山河控上游，
郁葱佳气满皇州。
风驱大漠浮云色，
天转滹沱落日流。
双阙金茎连紫极，
万家红树动高秋。
佩萸氿菊俱恩泽，
不是荆南独倚楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_173','送何太仆入贺还平凉','欧大任','明','长安何处望萧关，
醉里燕歌一解颜。
辑瑞北来趋魏阙，
封轺西去过秦山。
城连上郡羌胡远，
马饱中原战伐闲。
乘障莫嗟边吏苦，
玺书行召护军还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_174','癸亥明堂大祀礼成纪事','欧大任','明','甘泉高擢汉明庭，
更筑崇台礼万灵。
宗祀偶同书癸亥，
中兴谁复数殷丁。
芝生九叶铜池碧，
日抱重光玉树青。
前殿公卿频上寿，
万年何用禅云亭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_175','送姚匡叔之魏郡兼寄谢茂秦','欧大任','明','萧萧一骑渡洺河，
知有心期在薜萝。
漳滏波声黄叶下，
邢襄秋色白云过。
股肱三辅分庭少，
笔札诸生任侠多。
后夜西园应见月，
谢家新赋更如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_176','过沙河行','欧大任','明','离宫千里苑城开，
扈从当年尽汉才。
凤扆尚留清禁肃，
龙游曾奉属车来。
日高复道晨驱出，
星散周庐夜徼回。
宣曲长杨俱望幸，
彩云深护建章台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_177','谒长陵','欧大任','明','居庸叠嶂俯桑乾，
终古长陵王气盘。
凉雨石城千堞雪，
秋风金阙万松寒。
鼎湖弓剑胡天远，
原庙衣冠汉月残。
三驾犁庭思帝力，
北门封守在长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_178','阳翠岭','欧大任','明','丛霄积翠筑金墉，
仙仗曾过第一峰。
海日夜摇三殿玉，
园霜秋落七陵钟。
石当御路皆成鹿，
松起中天半是龙。
圣主合符临万国，
侍臣谁更颂东封。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_179','送李尚宝册封肃府','欧大任','明','曾使琉球海上行，
又驰关陇别承明。
兰山星散千秋垒，
榆谷天连万里城。
负弩绛驺迎玉节，
直庐青琐忆金茎。
汉家茅土雄边镇，
从此河湟不用兵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_180','送沈给事册封周府','欧大任','明','礼重亲藩命汉官，
手持金册出长安。
睢阳旧苑鸣驺入，
洛涘名园载酒欢。
积雪歌声犹缥缈，
夹池竹色尚檀栾。
相如亦有游梁兴，
何日平台醉后看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_181','送陈侍御道襄出按闽中','欧大任','明','天书朝捧禁城西，
骢马翩翩向晚嘶。
三策锁闱周礼乐，
六条行部越山溪。
频年戈甲穿篁竹，
此日渔樵罢鼓鼙。
绝徼早宣明主意，
勋名麟阁待君题。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_182','答施虞部曾缮部同直省中见怀','欧大任','明','对直寒宵向省闱，
仙郎词赋有光辉。
高悬霜月联曹近，
闲锁冰厅见吏稀。
梦隔关城砧杵急，
心随江汉雁鸿飞。
草玄寂寞无人问，
自笑长安一布衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_183','送黄参军赴闽幕','欧大任','明','君行气激五都豪，
闽越频年尚属櫜。
簪袅军劳秦爵贵，
奉常家学汉庭高。
图中按垒窥鱼腹，
幕下持觞论豹韬。
别去从军诗早寄，
故人还赠吕虔刀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_184','病中曾缮部携酒同黎秘书夜过得长字','欧大任','明','并马移尊问草堂，
茂陵秋色正苍苍。
城头笛起关山月，
槛外砧飞汉苑霜。
多病更堪羁思苦，
清欢其奈鬓丝长。
芸台水部能来往，
倦客浑忘在异乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_185','次夕黎秘书携酒曾缮部同过得霄字','欧大任','明','故人尊酒慰萧条，
并控骅骝意气骄。
郢里高歌回白雪，
燕台寒色满青霄。
城边明月鸿声起，
灯下清霜木叶飘。
此夕谢庄惭作赋，
词臣多在圣明朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_186','病起曾缮部夜过','欧大任','明','倦疾柴门夜不扃，
三年萧寺只沉冥。
瀑窗药试疑瞳碧，
山笥书成愧汗青。
明月颇思玄度咏，
浊醪能问子云亭。
他宵松落空坛静，
谁共幽人石上听。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_187','施虞部敦甫寄诗问予卧病次韵奉答','欧大任','明','萧斋偃卧即山林，
门掩藜床岁月深。
市里玉壶聊混俗，
省中词客限同心。
拥衾洛下书生咏，
击节幽州马客吟。
赖有故人相慰藉，
不须重问橐中金。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_188','十月虏警书事三首','欧大任','明','朔气初飞万树霜，
惊传胡马过渔阳。
从军岂乏三河少，
度漠曾招六郡良。
鸣镝月寒窥雁塞，
射雕云暗散龙荒。
皇威赤羽劳诸将，
不似周王拥白狼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_189','十月虏警书事三首','欧大任','明','甘泉烽火到长安，
阙下衣冠立马看。
北转储胥刍粟富，
西来骠骑雪霜寒。
观兵帐外期超距，
拜将庭中议筑坛。
细柳已屯江总制，
月明羌笛满桑乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_190','十月虏警书事三首','欧大任','明','关塞秋阴暗白登，
飞狐道上羽书仍。
云屯汉卒徵三辅，
风急胡笳过七陵。
暂向太原称薄伐，
已知吉甫佐中兴。
书生亦有燕然颂，
待勒恒山第几层。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_191','答张民部饷军左安门寒夜见寄','欧大任','明','飞刍忽上白云边，
知尔登楼啸远天。
半夜军声胡垒月，
万家寒色蓟门烟。
檄成楯鼻提兵日，
箭落旄头破虏年。
投笔欲随骠骑去，
汉庭勋业在祁连。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_192','次韵酬曾缮部以三斋居省中见怀','欧大任','明','燕台风起暮萧骚，
念我偏题尺牍劳。
阔略幸无三府辟，
激昂终愧五陵豪。
公车岁月囊钱尽，
郎署云霄剑佩高。
停辇若逢明主问，
莫言宾客有绨袍。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_193','和梁彦国虏退后行经三河诸村落慨然见寄','欧大任','明','战后秋阴蓟柳疏，
怜君驻马为踌躇。
烽沉万垒荒烟外，
鬼哭千村野烧馀。
霜草有狐啼废井，
夕阳无鸟入残墟。
防胡李牧须频遣，
莫更边庭走檄书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_194','兵后梁彦国自滦州见过','欧大任','明','辽海君如管幼安，
萧条一骑客行难。
堠边星落秦皇戍，
战后云愁汉将坛。
驿路飞沙千里暗，
海风吹雪万山寒。
灯前独照昆吾剑，
长得蛟龙夜夜看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_195','冬夜同梁彦国宿永光寺禅房怀故园诸子得来字','欧大任','明','江南词赋有群才，
曾共高僧社里来。
人忆歌骊辞粤峤，
客疑招骏上燕台。
寒翻贝叶斋前诵，
香识梅花雪后开。
惟与许询禅此夕，
故园书待雁飞回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_196','雪中同梁彦国过文寿承学舍','欧大任','明','袖中怀刺倦尘沙，
清晓寻君坐日斜。
客食空斋惟苜蓿，
宦情高阁有梅花。
庭阴独下孤山鹤，
禁雪遥栖万树鸦。
经学汉儒推博士，
何人江左更名家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_197','雪夜同惟敬饯别彦国还卢龙得高字','欧大任','明','浊酒寒宵共尔曹，
明朝东去客途劳。
山窥上谷孤城月，
关倚玄菟万里涛。
黄竹当歌燕雪积，
白云随骑朔风高。
期君早献甘泉赋，
金马词臣待彩毫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_198','送许舍人稚干请告还灵宝','欧大任','明','金门侍从捧纶音，
去采三花结远心。
令伯表陈臣分浅，
茂陵书在主恩深。
雪凝嵩少扶藜往，
云起殽函驻马吟。
东阁故人应暂别，
岂容簪绂卧山林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_199','送方宪副定之备兵饶州','欧大任','明','使君千骑出长安，
干越新开大将坛。
番令古城楼橹壮，
康郎春浪舳舻寒。
军容班剑风云起，
宾从胡床雪月残。
遥想雅歌闲对酒，
芝山应是几回看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_200','冬至斋居后惟敬夜过得残字','欧大任','明','君从紫阁宿高寒，
下直还能访鹖冠。
惇史书馀云未散，
太常斋后雪初残。
千官肃穆骖鸾辂，
万骑周遭傍泰坛。
闻道星辰环幄殿，
侍臣执盖月中看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_201','同文休承顾汝和黎惟敬于虎圈观西域所进狮子','欧大任','明','禁苑般般绕象舆，
伏狮何幸仰宸居。
风驱林邑千山外，
云拥条支万里馀。
清庙已歌天马曲，
君王犹纳旅獒书。
更闻九译来朝贡，
太史编年在石渠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_202','甲子元日早朝','欧大任','明','千官催入紫宸班，
缥缈炉烟夹仗间。
晓日洛中新甲子，
春风燕甸旧河山。
凯成骠骑频归阙，
诏许呼韩近款关。
共听太平元会曲，
彩云飞处候龙颜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_203','经南内','欧大任','明','沉沉清禁转朱扉，
深锁松阴碧石围。
汉月曾窥青鸟去，
朔云先拥白狼归。
雅翻宫雪璚楼过，
龙喷山泉玉殿飞。
司竹老臣犹望幸，
太平无事宴游稀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_204','登辽后妆楼','欧大任','明','䌽槛雕阑半已荒，
房栊树色隐苍苍。
年深冻藓迷妆匣，
人去秋云锁屧廊。
玉镜尚悬辽海月，
璚花不散蓟门霜。
三千部落无劳望，
鸭绿江头雁几行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_205','上元日望大高玄殿灯火有赋','欧大任','明','太一祈年肃盛仪，
灯前亲拜竹宫时。
燎烟夕殿皆青玉，
法供春筵尽紫芝。
雍畤旧传周室礼，
汾阴今侍汉家祠。
云霄赋客多如雨，
持橐何人独鬓丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_206','送钟公琪改令博白','欧大任','明','移官因得故园游，
津吏先迎郁水舟。
监郡久知皮氏长，
赐书还问偃师侯。
装轻片石无劳载，
山近丹砂且暂留。
万里登台应北望，
题诗须寄蓟门秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_207','送徐别驾赴吉安','欧大任','明','监郡多闲见吏能，
安成山水最堪称。
黄牛石出疑巫峡，
白鹭洲横似秣陵。
客至高斋悬榻下，
诗成燕寝异香凝。
明年地主应携我，
骑马青原更一登。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_208','送杨参军允恭守曲靖','欧大任','明','五陵冠盖祖行杯，
万里楼船晓日开。
越巂地形邛笮尽，
盘江秋色叶榆来。
客游南部能蛮语，
家出西京自楚才。
诸葛盟坛云树里，
褰帷应向此登台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_209','送林邦阳佥宪赴汴备兵陈州','欧大任','明','中原谈笑拥青油，
吹角河山万里秋。
猎骑风云生广武，
蒐兵旌旆过鸿沟。
尊前书记知能赋，
戏下材官待运筹。
不是玉关留客久，
明年应得拜宸旒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_210','送文休承赴吉水文学','欧大任','明','家学吴门比陆机，
一官犹着旧儒衣。
执经讲肆诸生满，
临帖山斋过客稀。
雪浪每从章浦见，
暮霞多入楚城飞。
石渠金马徵贤日，
时倚江云忆禁闱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_211','赠光禄李少卿请告还缙云省觐','欧大任','明','班衣归去意何如，
诏许仙都得暂居。
客舍难忘光禄酒，
卿家真见缙云书。
听莺早过双溪水，
下马先趋万石闾。
须忆柏梁台上宴，
天涯春色伴还车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_212','送沈祠部以安奉使因归省湖州','欧大任','明','冠盖都亭揖玉鞭，
故人多在蓟门天。
千山梦寐为郎日，
六传风云奉使年。
䌽服朝持新箬酒，
白蘋春送太湖船。
建章莫作经时别，
御柳轻摇万树烟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_213','寄徐子与','欧大任','明','汝南尊酒送征轮，
何事君为去国人。
汉日将军逢醉尉，
楚天渔父识孤臣。
瑶华独忆飘零远，
金埒空闻贵幸新。
早晚承明应再入，
谁容烟艇五湖春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_214','寄濮州苏子川子冲兄弟','欧大任','明','闻君濮上卧烟萝，
兄弟才名二谢多。
玉树春风飞梦远，
金茎佳气早鸿过。
钓台艇畔庄周石，
草阁帘前瓠子河。
倘忆倦游梁苑客，
可无书札慰蹉跎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_215','王户部宅红梅花','欧大任','明','东阁名花许共攀，
独怜疏影近雕阑。
彩霞忽散春城色，
绛雪犹飞夕照寒。
梦想海棠巴子树，
步随宫柳汉臣冠。
关山莫遣吹横笛，
留待江南醉客看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_216','春日同惟敬约卿过弘法寺访翠岩和尚','欧大任','明','鹿苑西连紫禁天，
斋心曾问远师禅。
五台戒向山中受，
双树花从雨后悬。
昼永鹤行春竹里，
年深松偃石窗前。
许询颇解閒来往，
杖锡何妨结静缘。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_217','同曾选部于野韩虞部子成夜集范职方于公宅','欧大任','明','匈奴远遁塞烟销，
尊俎曾筹万里遥。
士论总收燕騕袅，
将材今数汉嫖姚。
山公有启傅三署，
水部能诗冠六朝。
独笑荆高狂击筑，
醉来犹自问金貂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_218','答王百谷道馆病起对月见怀','欧大任','明','牍中新草献长杨，
渴似相如鬓已苍。
客去独吟松几月，
僧来同掩竹斋凉。
扁舟远兴因吴语，
斗酒高歌学楚狂。
东阁早闻奇士满，
秋风吾有芰荷裳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_219','送吕比部声甫守庐州','欧大任','明','虎竹初分霄汉间，
庐江小吏候濡关。
褰帷春雨劳农出，
悬榻高斋送客闲。
云起每从三祖石，
鹤来曾过八公山。
登楼不用怀京邑，
早晚承明入计还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_220','送冯屯部信伯补抚州','欧大任','明','襜帷南去问桑麻，
江燕飞飞引旆斜。
内史台边翻忍草，
夫人坛上散明霞。
铜陵夜月红泉酒，
绣幕春风玉茗花。
太小冯君称汉吏，
赐金何日到天涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_221','次韵答曾参戎子澄塞上行军见寄','欧大任','明','都亭别后忆驱驰，
大漠听笳汉将悲。
南去长缨曾自请，
北来骠骑一相随。
官刍召募飞应急，
军市酣歌散未迟。
宾客兰台虽已老，
燕然铭笔为君期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_222','惟敬席上喜思伯使还','欧大任','明','步兵厨里一尊深，
闻尔还镳喜不禁。
使者玉鱼亲走送，
故人金马独浮沉。
弹冠意气谁相许，
拄杖烟霞尚可寻。
醉后莫论烽火事，
并州空折白云心。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_223','约卿东巡以灵岩诸诗寄示闻已登岱岳','欧大任','明','灵岩寺里赋新诗，
千骑东方星斗随。
汉月颇窥三观石，
秦云多挂五松枝。
燕齐有客谈仙诀，
禽尚何年住岳期。
揽辔西风应奏草，
玉皇宫阙待亲祠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_224','送林维成宰邵阳','欧大任','明','双旌南去路偏长，
秋雁飞时白苧凉。
城浸烟波皆洞野，
花开山郭似河阳。
竹枝自渡湘妃水，
菰米先称楚客乡。
归赋上林还给札，
莫誇云梦献君王。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_225','十六夜同黎秘书吴侍御梁舍人集梦芝馆听管山人作吴歌','欧大任','明','千家明月照帘栊，
高咏凉天散步同。
木叶自能飞洛下，
秋声先已满云中。
银河影落词臣酒，
玉兔光摇御史骢。
醉后忽闻歌子夜，
禁城钟鼓思何穷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_226','送李太守实夫罢归闽中','欧大任','明','驱车落日满河梁，
欲别犹堪典鹔鹴。
把袂几人燕市酒，
裁书八月蓟城霜。
空令白雁随归客，
只为青山忆故乡。
君到南中荣橘柚，
应知三径未全荒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_227','送姜宪副宗孝之关中','欧大任','明','清朝侍从有光辉，
十载祠官直禁闱。
绣斧日边新赐诏，
油幢关外远宣威。
三秦豪杰分庭揖，
二华烟云绕座飞。
早向长杨陪羽猎，
汉家词赋似君稀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_228','答潘少承经赤花海上见怀','欧大任','明','三载离居忆酒垆，
秋深犹自滞燕都。
谁堪侠气弹孤剑，
独有归心寄五湖。
笛里关山新白发，
楼前星斗乱黄榆。
君看甲子泥涂客，
长啸烟中且钓鲈。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_229','送黄佥宪士弘入贺礼成取道南归为太夫人寿','欧大任','明','紫宸车马出长安，
仙掌秋深露已漙。
金鉴拜陈明主寿，
玉觞归献使臣欢。
家藏桂籍分鸾掖，
筵近梅花照豸冠。
闻道曾孙迎太姥，
画图何异幔亭看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_230','九日惟敬置酒与张刘管张四山人同赋','欧大任','明','白云箫瑟一尊开，
共佩萸囊上蓟台。
橘熟题书曾问讯，
菊荒为客未归来。
秋高大漠胡尘净，
日落长杨汉骑回。
惟羡故人今侍从，
飘零谁道子虚才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_231','重阳后一日同古比部黎秘书集张民部宅','欧大任','明','班生宁望酒泉封，
旅食重阳已再逢。
紫闼梦悬金涧月，
白云心寄石闾松。
故人薄禄多官酿，
狂客酣歌待禁钟。
手把茱萸还强饮，
明年何地忆追从。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_232','同黎秘书曾缮部吴侍御万金吾出善果寺访冯侍御','欧大任','明','封事朝驰玉节孤，
青云冠盖满城隅。
客携擂具迎公子，
人向高阳问酒徒。
白简霜飞千里草，
紫驼秋落九关榆。
燕歌未歇传杯夕，
犹识风流在汉都。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_233','题玉洞桃花图赠大司空蔡公','欧大任','明','赤墀委佩更珊珊，
五十曾登汉将坛。
胡骑早闻安石墅，
洛师犹忆惠文冠。
关门紫气何人候，
湖水扁舟异日看。
万树桃花天目上，
山炉应熟九还丹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_234','送李子新还扬州因讯黄定父','欧大任','明','霜欺季子黑貂裘，
金尽长安不可留。
黯黯离情平谷月，
萧萧归骑广陵秋。
十年生事餐菰米，
万里勋名视蒯缑。
欲寄黄郎无尺素，
但凭飞梦过瓜洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_235','秋风','欧大任','明','萧瑟秋风天雨霜，
年来书剑半摧藏。
画眉京兆颇相笑，
舞袖长沙空自伤。
客计未应羞马牧，
宦情谁肯薄淮阳。
心知不待题麟阁，
犹得诙嘲陛楯郎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_236','秋风','欧大任','明','清切遥看西掖垣，
几人荐引登金门。
龙渊池出斗牛气，
凤诏天垂云雨恩。
醉白渐多嵩洛梦，
草玄已老蓬蒿园。
飘零短褐秋风客，
睥睨心期惟酒尊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_237','大理潘公雪夜邀同吴侍御黎秘书万金吾集','欧大任','明','夜深寒色照帘栊，
廷尉留宾似孟公。
且共持觞燕市里，
岂论结袜汉庭中。
秋风城阙闻清角，
积雪关山断暮鸿。
赋客此时惭授简，
独能沉醉倚青骢。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_238','雪夜同陆山人过张司理时张已补外陆将还山','欧大任','明','寒色千门日易低，
为君一过玉河堤。
月移赵瑟佳人起，
雪照吴钩侠客携。
官阁梅花孤梦后，
钓船春草五湖西。
天涯尺素题何处，
好忆燕台疋马嘶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_239','同吴约卿携酒访姚元白于慈仁寺因登毗卢阁得山字','欧大任','明','秦京久客待君还，
鹿苑相携霄汉间。
地涌飞楼云绕舄，
天连孤鸟日衔山。
高寒并见金茎影，
禁近初归玉笋班。
萧瑟秋风怜庾信，
江南何处望乡关。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_240','曾比部子玉宅同冯侍御黎秘书胡礼曹夜集','欧大任','明','华发金门隐岁星，
知君执戟爱沉冥。
凤毛家学闻江左，
马尾官书在汉廷。
醉后自能歌白雪，
灯前谁共舞青萍。
郊园赐沐承恩日，
曾恋松萝月满亭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_241','送刘评事少脩调望江令','欧大任','明','雪花燕甸马鞯寒，
又送鸣珂出禁銮。
三礼甲科郎选重，
大雷渔长主恩宽。
且因粳稻移家去，
岂谓风尘作吏难。
闻是尚方曾赐舄，
飞凫还望到长安。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_242','至日同姚元白苏子川黄定父吴约卿张羽王饮黎惟敬宅时元白将还白下羽王将之雷州','欧大任','明','阊阖阳生积雪光，
高城夕送雁千行。
江南不见梅花使，
蓟北空持柏叶觞。
银烛莫教歌管歇，
玉颜应笑鬓丝长。
风流渐觉词人散，
不待他年忆建章。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_243','雪中戴伯常见过','欧大任','明','晓雪如花片片飘，
鸣珂犹复问僧寮。
人寻洛下无行径，
客倦咸阳有敝貂。
苑树风吹珠错落，
禁城山拥玉岧峣。
冲泥欲跨银鞍去，
先访将军第五桥。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_244','赠张司理羽王之雷州','欧大任','明','酒尽征车不可留，
劳君万里拥缇油。
荔枝熟处江云湿，
杉叶飞时海郡秋。
赋后鹏抟多作浪，
尊前蜃起自成楼。
竹书岁报无冤狱，
前席从容待借筹。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_245','寄王仲房','欧大任','明','闻君久托远游心，
浮世行藏自陆沉。
掌记军中曾入幕，
飞书海上亦辞金。
扁舟夜钓黄湖冷，
精舍秋移白岳深。
谡谡松风何处听，
杖藜吾欲一相寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_246','次韵答顾玄纬见寄','欧大任','明','早买山田四十双，
扁舟归去老江乡。
谈禅有客期兰若，
看竹何人问草堂。
世许谷云工笔札，
自羞辕固少文章。
一轺欲访延陵子，
天末题书报雁行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_247','洞泉有仙人卢至柔遗迹顾光禄隐居在焉为赋是诗','欧大任','明','璨山深访羽人居，
洞酌亭前寄敝庐。
流水玉琴挥轸外，
秋风金涧听松馀。
曾攀丘垄乌啼树，
尚忆云窗鸟篆书。
江左周颙归未得，
十年猿鹤意何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_248','诚意伯刘公宅同群公宴集得孤字','欧大任','明','东阁梅花照玉壶，
上公开宴集城隅。
汉京授简新词客，
燕市衔杯旧酒徒。
盟府勋名班剑在，
中天邸第白云扶。
长裾不少清狂兴，
醉散朱门月色孤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_249','吴明卿上计至都下','欧大任','明','使者归来谒建章，
郁葱佳气满咸阳。
禁中乐府歌朱鹭，
阙下书生对白狼。
鸣玉班行收客泪，
赐金颜色借恩光。
子虚颇有相如赋，
侍从无劳上汉皇。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_250','岁暮次韵答施虞部','欧大任','明','避喧金马即山堂，
燎玉空瞻紫禁光。
把酒病犹逢汉腊，
披裘寒自拂胡霜。
家人椒颂劳相忆，
驿使梅花远莫将。
惟有吟诗何水部，
共凭高阁望江乡。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_251','送徐子明赴苍梧参军','欧大任','明','跃马都门意气生，
飞书骆越旧知名。
炎洲道路三千里，
沧海戈船十万兵。
岂为故人誇负弩，
祇缘多难请长缨。
伏波门下南征曲，
更听袁郎玉笛声。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_252','冬日同文博士寿承黎秘书惟敬集顾舍人汝和宅','欧大任','明','逢君休沐下东华，
邀赏高斋到日斜。
已道书钞麟趾殿，
真看画在虎头家。
香炉云起匡山石，
金灶烟分顾渚茶。
闻道五陵公子醉，
只誇银甲拨琵琶。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_253','同项思尧黎惟敬诸君饮顾光禄汝所齐中乃兄汝由直阁汝和舍人皆在会','欧大任','明','绛蜡金尊夜不寒，
岂知今夕在长安。
步兵厨里酒新熟，
拥衲龛前雪未残。
家有赐书班嗣富，
名齐伯仲季方难。
醉来索笑梅花下，
何似扬州水阁看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_254','同惟敬夜过明卿得台字','欧大任','明','送腊尊醪日日开，
明星驱马凤城隈。
天知汲黯淮阳至，
人笑王生渤海来。
裘剑摧藏惟解饮，
风尘荏苒几怜才。
俸钱莫问今多少，
且共酣歌上蓟台。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_255','除夕卧病酬施虞部见召不赴因订早春之约兼呈曾郎中吴韩二员外','欧大任','明','东省屠苏念故人，
席门虚枉使车频。
愁深白发三年客，
梦破青山一病身。
玉醴想添新岁色，
金钱将醉曲江春。
申公已侧当时目，
犹得交欢侍从臣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_256','送庞侍御少南出按两浙二首','欧大任','明','明堂令布履端馀，
宪府霜飞按越初。
沧海潮回收万弩，
潢池氛净出单车。
探碑禹穴多奇字，
访士桐江有旧庐。
八使风流谁得似，
西京人望皂囊书。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_257','送庞侍御少南出按两浙二首','欧大任','明','同时学赋羡君成，
流落怜子十载情。
周室主书专柱史，
汉家掌故待诸生。
交游敢望弹冠出，
父老应随负弩迎。
浙水东西怀绣斧，
江花那得计王程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_258','瑞室诗为四明薛子熙赋','欧大任','明','明经旧署郑公乡，
南渡衣冠岁月长。
野火不惊焦处士，
山云常护鲁灵光。
藤交瀑下窗犹暗，
菊散霜前径未荒。
奇字祇今邻禹穴，
高楼还儗并梅梁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_259','诚意伯刘国桢使楚饯别于孙鸿胪宅得枝字','欧大任','明','燕台征骑早春时，
九陌青青折柳枝。
玉节星随周使者，
朱陵云识汉官仪。
澧兰尽入词人赋，
湘竹宁忘帝子思。
鸿雁从来飞不到，
天涯何处问归期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_260','陆使君道函入计还宝庆','欧大任','明','使者朝宗出帝阍，
赐金南去奉明恩。
飞花扑面驱邮传，
落日离心寄酒尊。
风曳珠旗云梦泽，
马嘶春草邵陵原。
上林奏赋嗟留滞，
待尔鸿书到蓟门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_261','清明前一日同方行人岳文学江张二山人集孙鸿胪宅得孙字','欧大任','明','三年持橐傍金门，
汉署还来问酒尊。
千叠浮云迷客舍，
五陵春草送王孙。
莺声半入华阳馆，
马首频窥灞水园。
他日看花携手客，
禁烟时节望中原。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_262','送魏顺甫使君上计还济南','欧大任','明','河梁垂柳拂雕鞍，
竹马争迎稚子欢。
燕筑深杯怀历下，
楚歌明月满长安。
黄金恩重君王赐，
白雪词高和者难。
别后椷书何处寄，
春鸿飞尽岱云寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_263','赠黎君华岑贞叔南还','欧大任','明','风起春城日易阴，
留君斗酒故情深。
弃繻暂出西游路，
献玉终酬北望心。
驿路新莺难驻马，
天涯久客易沾襟。
垆头诸少应相忆，
为报秋期在竹林。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_264','送冯侍御出按山西','欧大任','明','侍从当年草白麻，
西行绣斧有光华。
晋阳列署看双柏，
汾水鸣骢散五花。
霜落胡沙边燧暗，
星随汉使岳云斜。
建章正待筹边疏，
不用蒲稍入内家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_265','雨后饮苏子川宅望西山得花字','欧大任','明','西山爽气满窗纱，
丹凤城南日未斜。
翠黛遥分燕柳色，
青云平出岳莲花。
閤开双瀑长临涧，
鸟度诸峰半带霞。
尊酒却疑人境外，
谁知还醉近臣家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_266','送刘选部孟真请告还夷陵','欧大任','明','何事张衡咏四愁，
飞花春散凤皇楼。
暂辞起草诸郎直，
谁共鸣驺六传游。
三峡云帆巴子月，
一江风笛渚宫秋。
廷中最忆山公启，
兰佩荷裳未可留。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_267','送范职方于公奉使吴中','欧大任','明','侍从频年奉柏梁，
西风暂得过鲈乡。
出关偶作吴洲客，
负弩争迎汉署郎。
山下清溪通夕照，
城边白苧散秋凉。
輶轩归上江淮奏，
愿遣材官事朔方。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_268','答戴进士仪周','欧大任','明','燕市还来共酒杯，
笑予寄宿在灵台。
省中兰佩今堪结，
江上荷裳未可裁。
连骑岂知原宪病，
淩云空羡马卿才。
玉河烟柳年年色，
曾见何人奏赋回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_269','送毕兆先掌教安福','欧大任','明','与君少小竹斋谈，
此日青毡出淦南。
沧海蛟龙双跃剑，
蓟门风雨一分骖。
秋凉弦诵新茨野，
夜色楼台石鼓潭。
别后江鸿谁共听，
相思应有白云椷。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_270','送陈文学季谦赴信丰','欧大任','明','闻道儒林近岭边，
章江西上孝廉船。
片帆烟水三千里，
双剑风云二十年。
韦氏只今推世业，
文翁不敢倚先贤。
故人相送堪相笑，
犹得微官足酒钱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_271','徐子与入都见访','欧大任','明','蓟云千片拥骅骝，
把袂中原感旧游。
一别雪飞桐柏水，
三年书寄白蘋洲。
铜龙见尔鸣珂入，
金马怜予待诏留。
短发萧骚惟侠气，
紫貂还问酒家楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_272','初秋同张李陈三户部王山人柴文学集天坛曹道士院得窗字','欧大任','明','日午鸣钟迎客到，
仙童花下立双双。
当秋山色分松院，
过雨泉声冷石窗。
白鹤连翩参法席，
灵风萧飒满经幢。
词人兴在烟萝外，
有约还来倒玉缸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_273','弘法寺送徐子与谪长芦','欧大任','明','回首金门感慨多，
汉家迁客一悲歌。
玉珂秋散祇园树，
宝剑寒生易水波。
郡里太行新雁起，
尊前渤海白云过。
主恩不遣长沙去，
咫尺承明鬓已皤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_274','早秋同达水部集施虞部省中园亭得来字是日期曾缮部不至','欧大任','明','署中凉色满池台，
更有双尊出旧醅。
濯露蔬劳园吏给，
冒霜花为省郎开。
边烽幸绝甘泉报，
胡雁初从大漠来。
寄问东曹词赋客，
何时还共故人杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_275','讯沈祠部病','欧大任','明','病来秋叶满亭皋，
圣主斋居念礼曹。
露下金茎双阙迥，
月明瑶瑟五陵高。
四愁有客思江汉，
七发何人望海涛。
那得沈郎腰不瘦，
闭门犹是著书劳。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_276','秋夕卧病对月怀许维桢何启图二内翰','欧大任','明','卧游因病久盘桓，
曾记名山万里看。
雪后驱车过汝水，
月中摇艇入新安。
昔年白雁思传札，
此日铜龙阻握兰。
尊酒何因携二妙，
清光知在玉堂寒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_277','乙丑九日同古茂毨蒙廷俞张鸿与蒙廷纶张伯邻郭笃周饮伦绍周宅','欧大任','明','蓟城佳节忆烟皋，
尚喜东邻有浊醪。
赤管自怜频索米，
黄花犹得共持螯。
酒钱颇羡陶彭泽，
诗句深知谢法曹。
岁岁佩萸何处客，
归心偏恋五云高。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_278','送沈祠部谢病归吴兴','欧大任','明','独辞省署向烟萝，
金马其如病客何。
别骑关城惊雁早，
归舟江峤听猿多。
帘前讲肆逢严叟，
溪上清缨学楚歌。
知有郎中桑落酒，
兰桡将泛太湖波。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_279','中秋同社诸子集方侍御宅得中字','欧大任','明','醉客挥毫倚玉骢，
西园今夕正秋风。
关山一赋秦城上，
砧杵千声汉苑中。
歌后新凉生觱篥，
尊前清露滴梧桐。
庾公此兴应非浅，
月下何人赋最工。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_280','太霞洞天为永昌周象贤赋','欧大任','明','兰津渡口望天池，
曾见王乔来去时。
山气晓蒸华马国，
海云寒接碧鸡祠。
丹砂不用求勾漏，
采幔应看胜武夷。
觞客九霞堪一醉，
何年瑶水与君期。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_281','燕京秋夜登楼怀故园','欧大任','明','风起飞沙日易阴，
高城吹角此登临。
归人书去孤鸿杳，
游子心惊落叶深。
千垒浮云驱大旆，
万家明月拭清砧。
故园亦在沧江上，
烽火年年听捷音。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_282','南溪泛舟遇雨客有怀江南者共赋中字','欧大任','明','城西陂上晚溟濛，
越客扁舟望不穷。
渭水云沉波色里，
长杨秋在雨声中。
乍飞鹤子翻池白，
欲尽荷花坠露红。
多少燕姬愁翠黛，
共将离思寄江枫。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_283','送袁解元南归','欧大任','明','异乡携手客愁开，
秋色飘零酒一杯。
未论南州曾荐士，
只知东阁解怜才。
蓟门落叶千砧送，
沧海惊波一棹回。
已笑中涓求骏晚，
黄金宁不待君来。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_284','雨夜同薛文学晁秀才集吴侍御子沐宅','欧大任','明','君家绿酒照玻璃，
佳句还邀烛下题。
宫漏稀闻官舍里，
城云低度禁垣西。
铜街踏雨寒嘶马，
白简朝天曙听鸡。
他夕金龟能笑解，
二豪犹得醉相携。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_285','送戚进士世秀请告归泗州毕姻','欧大任','明','金门诏许出关遥，
淮水乘龙意气骄。
鳷鹊青云随去骑，
凤皇新月在鸣箫。
花摇屏烛春开宴，
星引天津夜度桥。
想是听鸡还戒旦，
含香催入圣明朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_286','子与约会沧州予将从德州南行不得过先寄此作','欧大任','明','献策无媒将远游，
萧萧一骑出卢沟。
白云不散青枫色，
明月独照黄河流。
欲赠生平三楚璞，
可怜离合双吴钩。
他时莫忆悲歌客，
别后何人燕市秋。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_287','寄李于鳞','欧大任','明','屏居犹在列仙乡，
十二楼台蜃雾旁。
客自函关占紫气，
世从鲁甸识灵光。
窗前海近弹琴润，
岳顶云来散帙凉。
难向此中歌白雪，
相将看日到扶桑。',NULL,'','{"preface": "十五年前，从公实闻于鳞甚著。公实已矣。于鳞今卧历下。仆时时思见其人，无由东行一访。前年入燕京，获览观于鳞歌诗于殿卿所。今年春，明卿有寄《题白雪楼诗》，邀仆同作。而子与则谓仆曰：“昔予二三兄弟，旁得奇士，即四五千里外移书相告，辄引满大釂以为欢，岂可使于鳞不知南海有欧生耶？”因遣书通知。仆感斯言，赋寄于鳞二诗，幸题于白雪楼上，酒酣耳热时，命苍头歌之。他日，客有燃藜握管而过者，必欧生也。", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_288','寄李于鳞','欧大任','明','高楼不下绝风尘，
傲吏当年早乞身。
金匮山经藏岱岳，
石渠门客出咸秦。
酒曾累日逢中圣，
赋更何时奏大人。
海内从来誇御李，
愿从骑鹿过千春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_289','雪夜古比部携酒雷比部同过','欧大任','明','蓟门积雪九衢光，
犹得相随酒榼狂。
紫禁地分文学掾，
白云天远尚书郎。
骊驹不用催官骑，
鸾鹤偏能恋帝乡。
此夜王猷好乘兴，
他年无忆剡溪长。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_290','送范太史伯祯奉使册封鲁王','欧大任','明','殿前三策献宸旒，
人识词林第一流。
玉节西分周太史，
金符东授汉诸侯。
古城弦诵兼风雪，
复壁图书烛斗牛。
邹鲁千秋还讲业，
归来何异马迁游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_291','余省觐岭外马进士使辽东饮别霍进士爱大宅得真字','欧大任','明','祖筵雪色照城闉，
海内交情尔最真。
岭表辽阳明日路，
貂裘狐帽异乡身。
尊前星斗关山远，
阙下衣冠气象新。
燕赵悲歌还此地，
重来击筑更何人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_292','诸太史邀饯席上留别','欧大任','明','玉署开尊雪满庐，
勾陈东望逼天居。
浮沉祇自逢宾戏，
浅薄何能赋子虚。
离夜肯留文学宴，
聚星今得史官书。
一经南去还持橐，
遥忆名儒议石渠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_293','大理邹卿夜饯席上留别','欧大任','明','乌飞廷尉府中栖，
坐拥燕山玉嶂低。
半夜星辰丹凤绕，
千门冰雪紫驼嘶。
避人谏草閒曾检，
爱客诗篇醉屡题。
我去扬州五湖月，
春鸿偏忆禁垣西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_294','张掖门留别曾以三缮部','欧大任','明','燕市千杯送我归，
中原交友似君稀。
易为易水悲歌泪，
难把河梁落日衣。
霜草台边孤骑去，
朔云天畔几鸿飞。
谁怜长乐听钟客，
独向江淮忆禁闱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_295','周子脩苏子川丁庸卿周汝砺孙文济孙文鼎项思尧黄汝会柴季通黄定父纪旭仁诸君枉饯席上留别','欧大任','明','高阳宁得少吾徒，
结客青萍日渐孤。
彯组尔应留汉署，
下帷人自出江都。
他乡梦里思琼树，
明月歌中倒玉壶。
别后迢迢怜尺素，
不知双鲤到淮无。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_296','张掖门再别曾缮部','欧大任','明','关前立马色苍苍，
抗手还同汉署郎。
双阙风云分去路，
千山冰雪照离觞。
蓟门赋后馀双鬓，
碣石书归待八行。
别汝相思无远近，
天涯一望九回肠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_297','过河间郡','欧大任','明','幽州甲士何翩翩，
自许黄金召募年。
插羽东翻沧海日，
鸣铙北扫塞垣烟。
路旁小儿能杀马，
河间姹女工数钱。
不见听鸡刘越石，
侠客中原空自怜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_298','渡河入德州却寄慈仁和尚','欧大任','明','鲁门一望水如渑，
渐远长安隔五陵。
钜野旆旌苍树出，
暮天楼橹白云升。
鸦归返照啼高冢，
马饮寒流顾断冰。
行役驱驰飞锡远，
题书心愧雁门僧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_299','登岱二首','欧大任','明','天风飒飒起秦松，
鸾鹤相随上岱宗。
石暗客窥千岁字，
雪残僧扣万山钟。
翠华日月开虞狩，
玉检云霞护汉封。
曾是仙人期六博，
夜来还借二茅龙。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_300','登岱二首','欧大任','明','岁杪东游亦快哉，
石闾高倚避风台。
射牛不用诸生议，
牵狗疑逢老父来。
舄外波涛银阙涌，
杯前齐鲁白云开。
谁能婚嫁迟栖岳，
禽尚何年向此回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_301','阙里谒孔庙','欧大任','明','尼泗千年启閟宫，
坛前冠佩讲时同。
凤衰歌后人何在，
麟出书成道已穷。
鲁壁藏经残简积，
汉祠祝史太牢崇。
东来邹峄观乡射，
犹听金丝到庙中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_302','谒孔林','欧大任','明','世家何但表东州，
梁木空摧万古愁。
鸟下山犹庐冢夕，
叶彫林似奠楹秋。
岱云不向城边散，
泗水长悬天上流。
落日缁帷延首地，
松门风急下寒沟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_303','衍圣公留宴','欧大任','明','堂开曲阜带林霞，
西第歌钟起暮鸦。
车服尚传秦博士，
宫墙犹识鲁东家。
烟生宝鼎皆成篆，
雪积琼枝半缀花。
岱岳诸峰明月色，
相将终宴向庭斜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_304','过薛城','欧大任','明','公子倾身下士年，
至今侠气尚翩翩。
三千客散荒秋草，
七十城空锁夕烟。
长铗飘零收慷慨，
高台歌舞惜婵娟。
不须更奏雍门曲，
牧竖樵童满墓田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_305','夜登徐州驿楼','欧大任','明','汴泗交流重镇成，
千家雉堞听涛声。
浊河月涌台边迥，
衰草天连雪后平。
霸气只今销沛上，
楚歌犹自满彭城。
汉家更欲沉玄璧，
酾酒黄楼万古情。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_306','青口驿遇乡僧介公同登三祖山望灊皖天柱诸峰','欧大任','明','地布黄金玉作岑，
西来三祖古禅林。
山云半剪传衣色，
海石空留听偈心。
涧水供筵经雪净，
竹房清梵出烟深。
道人白鹤同僧去，
天柱还随杖锡寻。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_307','闻黎职方惟敬已趋金陵予自黄梅渡江过浔阳不得相见','欧大任','明','献岁东风彩鹢催，
浔阳难待故人回。
独驱涛色三湖过，
不见梅花五岭来。
持橐旧随鳷鹊观，
挥毫今忆凤凰台。
樱桃未熟还江北，
莫负金陵几百杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_308','江州城楼晚望','欧大任','明','家在渔村有钓蓑，
偶从簪弁失烟波。
怀人书札春鸿早，
作客江湖夜雨多。
匡岳千峰云不散，
浔阳九派路如何。
五噫岂似关东去，
回首中原一放歌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_309','瑞州官舍同黎比部晚酌净芳亭','欧大任','明','征轺计日问长亭，
筠上从君倒玉瓶。
宪府戟枝移竹院，
官池波色上莎厅。
频瞻南峤云俱白，
三渡西江草又青。
同得趋归家庆近，
茅堂灯火带春星。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_10_310','燕京秋夜闻砧','欧大任','明','丹凤城南夜正长，
万家明月捣衣裳。
忽惊落叶频沾臆，
不听悲笳亦断肠。
遮虏渐闻过马邑，
拔营曾报破龙荒。
豫愁绵折天山下，
那识弓胶瀚海旁。
书去再经燕草绿，
梦飞不到塞云黄。
玉关纵待封侯入，
祇得萧萧白发郎。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_10_311','秋夜登曾缮部省中楼同黎惟敬赋','欧大任','明','骋望遥天云，
迢迢带城阙。
关山一笛声，
况是高楼月。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_10_312','赠曹山人幼兴南还','欧大任','明','君看槐树陌，
何似桃花源。
独有长安梦，
相随还故园。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_10_313','张山人将游五岳过予寓舍为别二首','欧大任','明','暂揖市上鞭，
一送云中辔。
归时五游成，
示我青苔字。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_10_314','张山人将游五岳过予寓舍为别二首','欧大任','明','张公江海客，
亦诵龙虎文。
